CREATE TABLE SIGIP_CONTROL (ID NUMBER PRIMARY KEY CHECK (ID = 1), REVISION NUMBER DEFAULT 0 NOT NULL, INICIALIZADO NUMBER DEFAULT 0 NOT NULL CHECK (INICIALIZADO IN (0,1)))
/
CREATE TABLE SIGIP_AUXILIAR (ID VARCHAR2(256) PRIMARY KEY, ORDEN NUMBER NOT NULL, DATOS CLOB NOT NULL CHECK (DATOS IS JSON), REGISTRADO_EN TIMESTAMP(6) WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL)
/
CREATE TABLE SIGIP_USUARIO (ID VARCHAR2(256) PRIMARY KEY, ORDEN NUMBER NOT NULL, DATOS CLOB NOT NULL CHECK (DATOS IS JSON), REGISTRADO_EN TIMESTAMP(6) WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL)
/
CREATE TABLE SIGIP_PERFIL (ID VARCHAR2(256) PRIMARY KEY, ORDEN NUMBER NOT NULL, DATOS CLOB NOT NULL CHECK (DATOS IS JSON), REGISTRADO_EN TIMESTAMP(6) WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL, USUARIO_ID VARCHAR2(256) NOT NULL REFERENCES SIGIP_USUARIO(ID), AREA VARCHAR2(20) NOT NULL, ROL VARCHAR2(80) NOT NULL, REGIONAL VARCHAR2(128))
/
CREATE TABLE SIGIP_EJECUTOR (ID VARCHAR2(256) PRIMARY KEY, ORDEN NUMBER NOT NULL, DATOS CLOB NOT NULL CHECK (DATOS IS JSON), REGISTRADO_EN TIMESTAMP(6) WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL, AREA VARCHAR2(20) NOT NULL, REGIONAL VARCHAR2(128))
/
CREATE TABLE SIGIP_CATALOGO (ID VARCHAR2(256) PRIMARY KEY, ORDEN NUMBER NOT NULL, DATOS CLOB NOT NULL CHECK (DATOS IS JSON), REGISTRADO_EN TIMESTAMP(6) WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL, CATEGORIA VARCHAR2(100) NOT NULL, CODIGO VARCHAR2(256), VERSION NUMBER, ESTADO VARCHAR2(40), VIGENTE_DESDE VARCHAR2(32), VIGENTE_HASTA VARCHAR2(32))
/
CREATE TABLE SIGIP_PARAMETRO (ID VARCHAR2(256) PRIMARY KEY, ORDEN NUMBER NOT NULL, DATOS CLOB NOT NULL CHECK (DATOS IS JSON), REGISTRADO_EN TIMESTAMP(6) WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL, AREA VARCHAR2(20), TIPO VARCHAR2(100), VERSION VARCHAR2(256), ESTADO VARCHAR2(40), VIGENTE_DESDE VARCHAR2(32), VIGENTE_HASTA VARCHAR2(32))
/
CREATE TABLE SIGIP_CALENDARIO (ID VARCHAR2(256) PRIMARY KEY, ORDEN NUMBER NOT NULL, DATOS CLOB NOT NULL CHECK (DATOS IS JSON), REGISTRADO_EN TIMESTAMP(6) WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL)
/
CREATE TABLE SIGIP_CASO (ID VARCHAR2(256) PRIMARY KEY, ORDEN NUMBER NOT NULL, DATOS CLOB NOT NULL CHECK (DATOS IS JSON), REGISTRADO_EN TIMESTAMP(6) WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL, AREA VARCHAR2(20) NOT NULL, IDENTIFICADOR VARCHAR2(256) NOT NULL, UNIQUE (AREA, IDENTIFICADOR), CHECK (AREA IN ('INVESTIGACION','VICTIMAS')))
/
CREATE TABLE SIGIP_SOLICITUD (ID VARCHAR2(256) PRIMARY KEY, ORDEN NUMBER NOT NULL, DATOS CLOB NOT NULL CHECK (DATOS IS JSON), REGISTRADO_EN TIMESTAMP(6) WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL, CASO_ID VARCHAR2(256) NOT NULL REFERENCES SIGIP_CASO(ID), AREA VARCHAR2(20) NOT NULL, TITULAR_ID VARCHAR2(256) NOT NULL)
/
CREATE TABLE SIGIP_VERSION_SOL (ID VARCHAR2(256) PRIMARY KEY, ORDEN NUMBER NOT NULL, DATOS CLOB NOT NULL CHECK (DATOS IS JSON), REGISTRADO_EN TIMESTAMP(6) WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL, SOLICITUD_ID VARCHAR2(256) NOT NULL REFERENCES SIGIP_SOLICITUD(ID), VERSION NUMBER NOT NULL, CONTENIDO CLOB NOT NULL CHECK (CONTENIDO IS JSON), UNIQUE (SOLICITUD_ID, VERSION), CHECK (VERSION > 0))
/
CREATE OR REPLACE TRIGGER SIGIP_VERSION_SOL_INM BEFORE UPDATE OR DELETE ON SIGIP_VERSION_SOL FOR EACH ROW BEGIN IF DELETING THEN RAISE_APPLICATION_ERROR(-20001, 'Version inmutable'); ELSIF DBMS_LOB.COMPARE(:OLD.CONTENIDO, :NEW.CONTENIDO) <> 0 THEN RAISE_APPLICATION_ERROR(-20001, 'Contenido inmutable'); END IF; END;
/
CREATE TABLE SIGIP_ITEM_SOLICITUD (ID VARCHAR2(256) PRIMARY KEY, ORDEN NUMBER NOT NULL, DATOS CLOB NOT NULL CHECK (DATOS IS JSON), REGISTRADO_EN TIMESTAMP(6) WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL, SOLICITUD_ID VARCHAR2(256) NOT NULL REFERENCES SIGIP_SOLICITUD(ID), AREA VARCHAR2(20) NOT NULL, SERVICIO VARCHAR2(256), ESTADO VARCHAR2(80) NOT NULL, EJECUTOR_ID VARCHAR2(256) REFERENCES SIGIP_EJECUTOR(ID), ASIGNACION_ID VARCHAR2(256))
/
CREATE TABLE SIGIP_ASIGNACION (ID VARCHAR2(256) PRIMARY KEY, ORDEN NUMBER NOT NULL, DATOS CLOB NOT NULL CHECK (DATOS IS JSON), REGISTRADO_EN TIMESTAMP(6) WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL, ITEM_ID VARCHAR2(256) NOT NULL REFERENCES SIGIP_ITEM_SOLICITUD(ID), EJECUTOR_ID VARCHAR2(256) REFERENCES SIGIP_EJECUTOR(ID), POLITICA VARCHAR2(256))
/
CREATE OR REPLACE TRIGGER SIGIP_ASIGNACION_INM BEFORE UPDATE OR DELETE ON SIGIP_ASIGNACION BEGIN RAISE_APPLICATION_ERROR(-20001, 'Historial inmutable'); END;
/
CREATE TABLE SIGIP_TRANSICION (ID VARCHAR2(256) PRIMARY KEY, ORDEN NUMBER NOT NULL, DATOS CLOB NOT NULL CHECK (DATOS IS JSON), REGISTRADO_EN TIMESTAMP(6) WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL, ITEM_ID VARCHAR2(256) NOT NULL REFERENCES SIGIP_ITEM_SOLICITUD(ID), UNIQUE (ITEM_ID, ORDEN))
/
CREATE OR REPLACE TRIGGER SIGIP_TRANSICION_INM BEFORE UPDATE OR DELETE ON SIGIP_TRANSICION BEGIN RAISE_APPLICATION_ERROR(-20001, 'Historial inmutable'); END;
/
CREATE TABLE SIGIP_PERSONA_SOLICITUD (ID VARCHAR2(256) PRIMARY KEY, ORDEN NUMBER NOT NULL, DATOS CLOB NOT NULL CHECK (DATOS IS JSON), REGISTRADO_EN TIMESTAMP(6) WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL, SOLICITUD_ID VARCHAR2(256) NOT NULL REFERENCES SIGIP_SOLICITUD(ID), VERSION_SOL NUMBER NOT NULL, GRUPO_ID VARCHAR2(64) NOT NULL, UNIQUE (SOLICITUD_ID, VERSION_SOL, GRUPO_ID, ORDEN), CHECK (VERSION_SOL >= 0))
/
CREATE OR REPLACE TRIGGER SIGIP_PERSONA_SOLICITUD_INM BEFORE UPDATE OR DELETE ON SIGIP_PERSONA_SOLICITUD BEGIN RAISE_APPLICATION_ERROR(-20001, 'Historial inmutable'); END;
/
CREATE TABLE SIGIP_DOCUMENTO (ID VARCHAR2(256) PRIMARY KEY, ORDEN NUMBER NOT NULL, DATOS CLOB NOT NULL CHECK (DATOS IS JSON), REGISTRADO_EN TIMESTAMP(6) WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL, SOLICITUD_ID VARCHAR2(256) NOT NULL REFERENCES SIGIP_SOLICITUD(ID), ITEM_ID VARCHAR2(256) REFERENCES SIGIP_ITEM_SOLICITUD(ID), CLASE VARCHAR2(32) NOT NULL)
/
CREATE OR REPLACE TRIGGER SIGIP_DOCUMENTO_INM BEFORE UPDATE OR DELETE ON SIGIP_DOCUMENTO BEGIN RAISE_APPLICATION_ERROR(-20001, 'Historial inmutable'); END;
/
CREATE TABLE SIGIP_VERSION_DOCUMENTO (ID VARCHAR2(256) PRIMARY KEY, ORDEN NUMBER NOT NULL, DATOS CLOB NOT NULL CHECK (DATOS IS JSON), REGISTRADO_EN TIMESTAMP(6) WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL, DOCUMENTO_ID VARCHAR2(256) NOT NULL REFERENCES SIGIP_DOCUMENTO(ID), VERSION NUMBER NOT NULL, VERSION_SOL NUMBER, CONTENIDO CLOB NOT NULL CHECK (CONTENIDO IS JSON), UNIQUE (DOCUMENTO_ID, VERSION), CHECK (VERSION > 0))
/
CREATE OR REPLACE TRIGGER SIGIP_VERSION_DOCUMENTO_INM BEFORE UPDATE OR DELETE ON SIGIP_VERSION_DOCUMENTO FOR EACH ROW BEGIN IF DELETING THEN RAISE_APPLICATION_ERROR(-20001, 'Version inmutable'); ELSIF DBMS_LOB.COMPARE(:OLD.CONTENIDO, :NEW.CONTENIDO) <> 0 THEN RAISE_APPLICATION_ERROR(-20001, 'Contenido inmutable'); END IF; END;
/
CREATE TABLE SIGIP_BORRADOR (ID VARCHAR2(256) PRIMARY KEY, ORDEN NUMBER NOT NULL, DATOS CLOB NOT NULL CHECK (DATOS IS JSON), REGISTRADO_EN TIMESTAMP(6) WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL, TITULAR_ID VARCHAR2(256) NOT NULL, AREA VARCHAR2(20) NOT NULL, REVISION NUMBER NOT NULL, CHECK (REVISION > 0))
/
CREATE TABLE SIGIP_OUTBOX (ID VARCHAR2(256) PRIMARY KEY, ORDEN NUMBER NOT NULL, DATOS CLOB NOT NULL CHECK (DATOS IS JSON), REGISTRADO_EN TIMESTAMP(6) WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL, CLAVE VARCHAR2(512) NOT NULL UNIQUE, ITEM_ID VARCHAR2(256) NOT NULL REFERENCES SIGIP_ITEM_SOLICITUD(ID), ESTADO VARCHAR2(80) NOT NULL)
/
CREATE TABLE SIGIP_AUDITORIA (ID VARCHAR2(256) PRIMARY KEY, ORDEN NUMBER NOT NULL, DATOS CLOB NOT NULL CHECK (DATOS IS JSON), REGISTRADO_EN TIMESTAMP(6) WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL)
/
CREATE OR REPLACE TRIGGER SIGIP_AUDITORIA_INM BEFORE UPDATE OR DELETE ON SIGIP_AUDITORIA BEGIN RAISE_APPLICATION_ERROR(-20001, 'Historial inmutable'); END;
/
CREATE INDEX SIGIP_ITEM_EJEC_EST ON SIGIP_ITEM_SOLICITUD(EJECUTOR_ID, ESTADO)
/
CREATE INDEX SIGIP_SOL_TITULAR ON SIGIP_SOLICITUD(TITULAR_ID, AREA)
/
CREATE INDEX SIGIP_OUT_ESTADO ON SIGIP_OUTBOX(ESTADO)
/
CREATE INDEX SIGIP_DOC_ITEM ON SIGIP_DOCUMENTO(ITEM_ID)
/
